<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Mini Spreadsheet</title>
  <style>
    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      padding: 20px;
      color: #172033;
      background: #eef2f7;
      font: 14px/1.4 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    .app {
      min-width: 600px;
      min-height: 400px;
      max-width: 1100px;
      margin: 0 auto;
      padding: 18px;
      background: #fff;
      border: 1px solid #cbd3df;
      border-radius: 10px;
      box-shadow: 0 8px 24px rgba(27, 39, 62, 0.1);
    }

    h1 {
      margin: 0 0 14px;
      font-size: 22px;
    }

    .toolbar {
      display: flex;
      align-items: flex-start;
      gap: 12px;
      margin-bottom: 16px;
    }

    button {
      min-height: 38px;
      padding: 8px 16px;
      border: 1px solid #1f5fbf;
      border-radius: 6px;
      color: #fff;
      background: #286fd1;
      font: inherit;
      font-weight: 600;
      cursor: pointer;
    }

    button:hover {
      background: #1f5fbf;
    }

    button:active {
      transform: translateY(1px);
    }

    #csv {
      flex: 1;
      min-width: 350px;
      height: 76px;
      padding: 8px;
      border: 1px solid #aeb9c8;
      border-radius: 6px;
      resize: vertical;
      font: 12px/1.35 ui-monospace, SFMono-Regular, Consolas, monospace;
    }

    .sheet-wrap {
      overflow: auto;
      border: 1px solid #aeb9c8;
      background: #fff;
    }

    #grid {
      display: grid;
      grid-template-columns: 46px repeat(10, minmax(82px, 1fr));
      width: max-content;
      min-width: 100%;
    }

    .corner,
    .column-header,
    .row-header {
      display: flex;
      align-items: center;
      justify-content: center;
      min-height: 34px;
      color: #344054;
      background: #e9eef5;
      border-right: 1px solid #aeb9c8;
      border-bottom: 1px solid #aeb9c8;
      font-weight: 700;
      user-select: none;
    }

    .cell {
      width: 100%;
      min-width: 82px;
      height: 34px;
      padding: 5px 7px;
      border: 0;
      border-right: 1px solid #d4dae3;
      border-bottom: 1px solid #d4dae3;
      border-radius: 0;
      outline: none;
      color: #172033;
      background: #fff;
      font: 13px ui-monospace, SFMono-Regular, Consolas, monospace;
    }

    .cell:focus {
      position: relative;
      z-index: 1;
      box-shadow: inset 0 0 0 2px #2878e3;
      background: #f8fbff;
    }

    .cell.error:not(:focus) {
      color: #b42318;
      background: #fff2f0;
      font-weight: 700;
    }
  </style>
</head>
<body>
  <main class="app">
    <h1>Mini Spreadsheet</h1>

    <div class="toolbar">
      <button id="export" type="button">Export CSV</button>
      <textarea id="csv" aria-label="Exported CSV" placeholder="CSV output appears here"></textarea>
    </div>

    <div class="sheet-wrap">
      <div id="grid" role="grid" aria-label="Spreadsheet"></div>
    </div>
  </main>

  <script>
    (() => {
      "use strict";

      const COLS = "ABCDEFGHIJ".split("");
      const ROWS = 10;
      const addresses = [];
      const addressSet = new Set();
      const rawValues = Object.create(null);
      const displayedValues = Object.create(null);
      const inputs = Object.create(null);
      const grid = document.getElementById("grid");

      for (let row = 1; row <= ROWS; row++) {
        for (const col of COLS) {
          const address = col + row;
          addresses.push(address);
          addressSet.add(address);
          rawValues[address] = "";
          displayedValues[address] = "";
        }
      }

      function makeHeader(text, className, role) {
        const header = document.createElement("div");
        header.className = className;
        header.textContent = text;
        header.setAttribute("role", role);
        return header;
      }

      grid.appendChild(makeHeader("", "corner", "presentation"));
      for (const col of COLS) {
        grid.appendChild(makeHeader(col, "column-header", "columnheader"));
      }

      for (let row = 1; row <= ROWS; row++) {
        grid.appendChild(makeHeader(String(row), "row-header", "rowheader"));

        for (const col of COLS) {
          const address = col + row;
          const input = document.createElement("input");
          input.type = "text";
          input.id = "cell-" + address;
          input.className = "cell";
          input.autocomplete = "off";
          input.spellcheck = false;
          input.setAttribute("role", "gridcell");
          input.setAttribute("aria-label", address);
          input.dataset.address = address;

          input.addEventListener("focus", () => {
            input.value = rawValues[address];
          });

          input.addEventListener("input", () => {
            rawValues[address] = input.value;
            recalculate();
          });

          input.addEventListener("blur", () => {
            rawValues[address] = input.value;
            recalculate();
          });

          input.addEventListener("keydown", event => {
            if (event.key === "Enter") {
              event.preventDefault();
              input.blur();
            }
          });

          inputs[address] = input;
          grid.appendChild(input);
        }
      }

      function normalizeAddress(address) {
        const normalized = String(address).trim().toUpperCase();
        if (!addressSet.has(normalized)) {
          throw new Error("Invalid cell address: " + address);
        }
        return normalized;
      }

      function tokenize(source) {
        const tokens = [];
        let index = 0;

        while (index < source.length) {
          const remaining = source.slice(index);
          const whitespace = remaining.match(/^\s+/);
          if (whitespace) {
            index += whitespace[0].length;
            continue;
          }

          const number = remaining.match(/^(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?/);
          if (number) {
            tokens.push({ type: "number", value: Number(number[0]) });
            index += number[0].length;
            continue;
          }

          const reference = remaining.match(/^([A-Za-z]+)(\d+)/);
          if (reference) {
            const address = (reference[1] + reference[2]).toUpperCase();
            if (!addressSet.has(address)) {
              throw new Error("Reference outside spreadsheet");
            }
            tokens.push({ type: "reference", value: address });
            index += reference[0].length;
            continue;
          }

          const char = source[index];
          if ("+-*/()".includes(char)) {
            tokens.push({ type: char });
            index++;
            continue;
          }

          throw new Error("Unexpected token");
        }

        tokens.push({ type: "eof" });
        return tokens;
      }

      function parseFormula(source) {
        const tokens = tokenize(source);
        let position = 0;
        const dependencies = new Set();

        function current() {
          return tokens[position];
        }

        function consume(type) {
          if (current().type !== type) {
            throw new Error("Expected " + type);
          }
          return tokens[position++];
        }

        function parseExpression() {
          let node = parseTerm();
          while (current().type === "+" || current().type === "-") {
            const operator = tokens[position++].type;
            node = {
              type: "binary",
              operator,
              left: node,
              right: parseTerm()
            };
          }
          return node;
        }

        function parseTerm() {
          let node = parseUnary();
          while (current().type === "*" || current().type === "/") {
            const operator = tokens[position++].type;
            node = {
              type: "binary",
              operator,
              left: node,
              right: parseUnary()
            };
          }
          return node;
        }

        function parseUnary() {
          if (current().type === "+" || current().type === "-") {
            const operator = tokens[position++].type;
            return {
              type: "unary",
              operator,
              value: parseUnary()
            };
          }
          return parsePrimary();
        }

        function parsePrimary() {
          if (current().type === "number") {
            return {
              type: "number",
              value: consume("number").value
            };
          }

          if (current().type === "reference") {
            const address = consume("reference").value;
            dependencies.add(address);
            return {
              type: "reference",
              address
            };
          }

          if (current().type === "(") {
            consume("(");
            const node = parseExpression();
            consume(")");
            return node;
          }

          throw new Error("Expected number, reference, or parenthesis");
        }

        const ast = parseExpression();
        consume("eof");

        return {
          ast,
          dependencies: Array.from(dependencies)
        };
      }

      function parseAllCells() {
        const parsed = Object.create(null);

        for (const address of addresses) {
          const raw = rawValues[address];
          if (!raw.startsWith("=")) {
            parsed[address] = {
              formula: false,
              valid: true,
              dependencies: []
            };
            continue;
          }

          try {
            const result = parseFormula(raw.slice(1));
            parsed[address] = {
              formula: true,
              valid: true,
              ast: result.ast,
              dependencies: result.dependencies
            };
          } catch {
            parsed[address] = {
              formula: true,
              valid: false,
              dependencies: []
            };
          }
        }

        return parsed;
      }

      function findCycleCells(parsed) {
        let nextIndex = 0;
        const index = Object.create(null);
        const lowLink = Object.create(null);
        const stack = [];
        const onStack = new Set();
        const cycleCells = new Set();

        function visit(address) {
          index[address] = nextIndex;
          lowLink[address] = nextIndex;
          nextIndex++;
          stack.push(address);
          onStack.add(address);

          const info = parsed[address];
          const edges = info.formula && info.valid ? info.dependencies : [];

          for (const dependency of edges) {
            if (index[dependency] === undefined) {
              visit(dependency);
              lowLink[address] = Math.min(lowLink[address], lowLink[dependency]);
            } else if (onStack.has(dependency)) {
              lowLink[address] = Math.min(lowLink[address], index[dependency]);
            }
          }

          if (lowLink[address] === index[address]) {
            const component = [];
            let member;

            do {
              member = stack.pop();
              onStack.delete(member);
              component.push(member);
            } while (member !== address);

            if (component.length > 1) {
              component.forEach(cell => cycleCells.add(cell));
            } else {
              const only = component[0];
              const onlyInfo = parsed[only];
              if (
                onlyInfo.formula &&
                onlyInfo.valid &&
                onlyInfo.dependencies.includes(only)
              ) {
                cycleCells.add(only);
              }
            }
          }
        }

        for (const address of addresses) {
          if (index[address] === undefined) {
            visit(address);
          }
        }

        return cycleCells;
      }

      function isNumericText(text) {
        return /^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/.test(text.trim());
      }

      function recalculate() {
        const parsed = parseAllCells();
        const cycleCells = findCycleCells(parsed);
        const memo = Object.create(null);

        function evaluateAst(node) {
          if (node.type === "number") {
            return { ok: true, value: node.value };
          }

          if (node.type === "reference") {
            const referenced = evaluateCell(node.address);
            if (!referenced.ok) {
              return { ok: false };
            }
            return { ok: true, value: referenced.numeric };
          }

          if (node.type === "unary") {
            const result = evaluateAst(node.value);
            if (!result.ok) return result;
            return {
              ok: true,
              value: node.operator === "-" ? -result.value : result.value
            };
          }

          const left = evaluateAst(node.left);
          const right = evaluateAst(node.right);
          if (!left.ok || !right.ok) {
            return { ok: false };
          }

          let value;
          switch (node.operator) {
            case "+": value = left.value + right.value; break;
            case "-": value = left.value - right.value; break;
            case "*": value = left.value * right.value; break;
            case "/": value = left.value / right.value; break;
            default: return { ok: false };
          }

          return { ok: true, value };
        }

        function evaluateCell(address) {
          if (memo[address]) {
            return memo[address];
          }

          const info = parsed[address];
          const raw = rawValues[address];

          if (!info.formula) {
            if (raw.trim() === "") {
              return (memo[address] = {
                ok: true,
                display: raw,
                numeric: 0
              });
            }

            if (isNumericText(raw)) {
              return (memo[address] = {
                ok: true,
                display: raw,
                numeric: Number(raw.trim())
              });
            }

            return (memo[address] = {
              ok: false,
              display: raw,
              numeric: NaN
            });
          }

          if (!info.valid) {
            return (memo[address] = {
              ok: false,
              display: "#ERR",
              numeric: NaN
            });
          }

          if (cycleCells.has(address)) {
            return (memo[address] = {
              ok: false,
              display: "#CYCLE",
              numeric: NaN
            });
          }

          const result = evaluateAst(info.ast);
          if (!result.ok) {
            return (memo[address] = {
              ok: false,
              display: "#ERR",
              numeric: NaN
            });
          }

          return (memo[address] = {
            ok: true,
            display: String(result.value),
            numeric: result.value
          });
        }

        for (const address of addresses) {
          displayedValues[address] = evaluateCell(address).display;
        }

        const focused = document.activeElement;
        for (const address of addresses) {
          const input = inputs[address];
          if (input !== focused) {
            input.value = displayedValues[address];
          }
          input.classList.toggle(
            "error",
            displayedValues[address] === "#ERR" ||
            displayedValues[address] === "#CYCLE"
          );
        }
      }

      function csvEscape(value) {
        const text = String(value);
        if (/[",\r\n]/.test(text)) {
          return '"' + text.replace(/"/g, '""') + '"';
        }
        return text;
      }

      document.getElementById("export").addEventListener("click", () => {
        recalculate();
        const lines = [];

        for (let row = 1; row <= ROWS; row++) {
          const fields = [];
          for (const col of COLS) {
            fields.push(csvEscape(displayedValues[col + row]));
          }
          lines.push(fields.join(","));
        }

        document.getElementById("csv").value = lines.join("\n");
      });

      window.sheet = Object.freeze({
        set(address, value) {
          const normalized = normalizeAddress(address);
          rawValues[normalized] = value == null ? "" : String(value);
          recalculate();

          if (document.activeElement === inputs[normalized]) {
            inputs[normalized].value = rawValues[normalized];
          }
        },

        get(address) {
          return displayedValues[normalizeAddress(address)];
        },

        raw(address) {
          return rawValues[normalizeAddress(address)];
        }
      });

      recalculate();
    })();
  </script>
</body>
</html>
